$BackedUpFiles = New-Object System.Collections.Generic.List[string]
$CreatedFiles = New-Object System.Collections.Generic.List[string]

Write-Section "Backing up and applying AURA v0.8.4"

foreach ($entry in $Payloads.GetEnumerator()) {
    $relativePath = [string]$entry.Key
    $current = Join-Path $ProjectRoot $relativePath

    if (Test-Path -LiteralPath $current -PathType Leaf) {
        $backup = Join-Path $BackupRoot $relativePath

        Ensure-ParentDirectory -Path $backup

        Copy-Item `
            -LiteralPath $current `
            -Destination $backup `
            -Force

        $BackedUpFiles.Add($relativePath)
    }
    else {
        $CreatedFiles.Add($relativePath)
    }

    $target = Join-Path $ProjectRoot $relativePath

    Ensure-ParentDirectory -Path $target

    $base64Text = ([string]$entry.Value) -replace "\s", ""

    [System.IO.File]::WriteAllBytes(
        $target,
        [Convert]::FromBase64String($base64Text)
    )

    Write-Host ("Updated: " + $relativePath) -ForegroundColor DarkCyan
}

[System.IO.File]::WriteAllLines(
    (Join-Path $BackupRoot "backed_up_files.txt"),
    [string[]]$BackedUpFiles,
    (New-Object System.Text.UTF8Encoding($false))
)

[System.IO.File]::WriteAllLines(
    (Join-Path $BackupRoot "created_files.txt"),
    [string[]]$CreatedFiles,
    (New-Object System.Text.UTF8Encoding($false))
)

$RestoreScript = @'
[CmdletBinding()]
param()

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$BackupRoot = $PSScriptRoot
$ProjectRoot = Split-Path -Parent $BackupRoot
$BackedUpList = Join-Path $BackupRoot "backed_up_files.txt"
$CreatedList = Join-Path $BackupRoot "created_files.txt"

foreach ($relativePath in Get-Content -LiteralPath $BackedUpList) {
    if ([string]::IsNullOrWhiteSpace($relativePath)) {
        continue
    }

    $source = Join-Path $BackupRoot $relativePath
    $target = Join-Path $ProjectRoot $relativePath
    $parent = Split-Path -Parent $target

    New-Item `
        -ItemType Directory `
        -Path $parent `
        -Force | Out-Null

    Copy-Item `
        -LiteralPath $source `
        -Destination $target `
        -Force

    Write-Host ("Restored: " + $relativePath) -ForegroundColor Cyan
}

foreach ($relativePath in Get-Content -LiteralPath $CreatedList) {
    if ([string]::IsNullOrWhiteSpace($relativePath)) {
        continue
    }

    $target = Join-Path $ProjectRoot $relativePath

    if (Test-Path -LiteralPath $target -PathType Leaf) {
        Remove-Item -LiteralPath $target -Force

        Write-Host (
            "Removed newly created file: " + $relativePath
        ) -ForegroundColor Yellow
    }
}

Write-Host ""
Write-Host "AURA v0.8.4 was rolled back." -ForegroundColor Green
Write-Host "Rebuild and reinstall AURA before testing."
'@

[System.IO.File]::WriteAllText(
    (Join-Path $BackupRoot "RESTORE-AURA-v0.8.4.ps1"),
    $RestoreScript,
    (New-Object System.Text.UTF8Encoding($true))
)

Write-Section "Validating installed payload"

foreach ($entry in $ExpectedHashes.GetEnumerator()) {
    $relativePath = [string]$entry.Key
    $target = Join-Path $ProjectRoot $relativePath

    if (-not (Test-Path -LiteralPath $target -PathType Leaf)) {
        throw "Installed payload file is missing: $relativePath"
    }

    $actualHash = Get-Sha256 -Path $target

    if ($actualHash -ne [string]$entry.Value) {
        throw "Installed payload hash mismatch: $relativePath"
    }
}

Write-Host (
    "[PASS] " +
    [string]$ExpectedHashes.Count +
    " payload files match their SHA-256 hashes"
) -ForegroundColor Green

